window.AUTH=window.AUTH||{};window.AUTH["22-1165"]={"d":"22-1165","id":"2023/22-1165","n":"Macquarie Infrastructure Corp. v. Moab Partners, L.P.","briefs":[{"k":"petitioner","label":"Brief of petitioners Macquarie Infrastructure Corp., et al.","date":"2023-11-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-1165/289407/20231113141216216_MIC%20Opening%20Merits%20Brief%20-%20PRINT%20PDFA.pdf","side":"pet","n":81},{"k":"respondent","label":"Brief of respondent Barclays Capital Inc. in support of vacatur","date":"2023-11-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-1165/289445/20231113155738638_22-1165_brief.pdf","side":"res","n":11},{"k":"respondent","label":"Brief of respondent Moab Partners, L.P.","date":"2023-12-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-1165/293313/20231213162158729_Moab%20brief.pdf","side":"res","n":89},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2023-12-20","url":"https://www.supremecourt.gov/DocketPDF/22/22-1165/293867/20231220141226444_22-1165ac%20Macquarie%20v.%20Moab%20Partners.pdf","side":"us","n":52},{"k":"reply","label":"Reply of petitioners Macquarie Infrastructure Corp., et al.","date":"2024-01-05","url":"https://www.supremecourt.gov/DocketPDF/22/22-1165/295031/20240105132016708_MIC%20Merits%20Reply%20Brief%2022-1165%20-%20PRINT%20PDFA.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us2r13_8mjp.pdf","tr":true,"items":[{"t":"case","label":"Affiliated Ute Citizens of Utah v. United States","cite":"406 U.S. 128","y":1972,"id":"1971/70-78","sc":1,"sum":"The Ute Partition Act was designed to provide for the partition and distribution of the tribe's assets between the mixed-blood and fullblood members; for termination of federal supervision over the trust and restricted property of mixed-bloods; and for a development program for the full-bloods with a view toward terminating federal supervision of them. In addition to cash and land, the tribe owned oil, gas, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","2":"19","4":"10"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"38, 39"}},{"t":"case","label":"Basic Inc. v. Levinson","cite":"485 U.S. 224","y":1988,"id":"1987/86-279","sc":1,"op":1,"ar":2,"sum":"The Supreme Court held that there was no reason to artificially exclude merger conversations from the definition of materiality simply because they do not include specific prices.","sumSrc":"Oyez","by":{"0":"10, 22, 33","2":"2, 4, 25-27, 35, 42-45, 47, 26, 37","3":"13, 18, 22, 26","4":"7, 12, 13, 21"}},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"op":1,"sum":"A private damages action under Rule 10b-5 is confined to actual purchasers or sellers of securities and the Birnbaum rule bars respondent from maintaining this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 26, 31","1":"8","2":"32"}},{"t":"case","label":"Carvelli v. Ocwen Fin. Corp.","cite":"934 F.3d 1307","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/934/1307/","by":{"0":"29, 41"}},{"t":"case","label":"Cent. Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"0":"6, 7, 38","1":"8","2":"35"}},{"t":"case","label":"Chadbourne & Parke LLP v. Troice","cite":"571 U.S. 377","y":2014,"id":"2013/12-79","sc":1,"sum":"The Court held that the Securities Litigation Uniform Standards Act does not extend its scope beyond misrepresentations that are material to the sale of a closed financial security.","sumSrc":"Oyez","by":{"0":"32","4":"7"}},{"t":"case","label":"Chiarella v. United States","cite":"445 U.S. 222","y":1980,"id":"1979/78-1202","sc":1,"op":1,"sum":"A duty to disclose information arises if there is a relationship of trust and confidence between parties to the transaction. Chiarella had no such duty. He was not a corporate insider in the acquiring corporation and he did not receive confidential information from the target company.","sumSrc":"Oyez","by":{"0":"22, 23","2":"15, 21, 23-24","3":"2, 8, 19, 22, 29","4":"10, 13"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"op":2,"sum":"Petitioner accounting firm was retained to audit periodically a brokerage firm's books and records. Respondents, who were customers of the brokerage firm, invested in a securities scheme ultimately revealed as fraudulent and perpetrated by the firm's president and principal stockholder. After the fraud came to light, respondents filed an action for damages against petitioner under § 10 (b) of the Securities Exchange …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 6, 26","2":"16, 31","3":"3, 31, 32","4":"6"}},{"t":"case","label":"Goldman Sachs Grp., Inc. v. Ark. Tchr. Ret. Sys.","cite":"141 S. Ct. 1951","y":2021,"id":"2020/20-222","sc":1,"sum":"The generic nature of a misrepresentation in connection with the sale of securities often is important evidence of price impact that courts should consider at class certification; defendants bear the burden of persuasion to prove a lack of price impact by a preponderance of the evidence at class certification.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37","2":"21","3":"1","4":"10"}},{"t":"case","label":"Ind. Pub. Ret. Sys. v. SAIC, Inc.","cite":"818 F.3d 85","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/818/85/","by":{"0":"14"}},{"t":"case","label":"Janus Cap. Grp., Inc. v. First Derivative Traders","cite":"564 U.S. 135","y":2011,"id":"2010/09-525","sc":1,"ar":1,"sum":"The Court held that a service provider cannot be held liable for statements for which they are not directly responsible.","sumSrc":"Oyez","by":{"0":"8, 20, 22, 34","2":"36, 40","4":"2, 12, 13"}},{"t":"case","label":"Kokesh v. Sec. & Exch. Comm’n","cite":"581 U.S. 455","y":2017,"id":"2016/16-529","sc":1,"sum":"The Court held that Securities and Exchange Commission (SEC) disgorgement functions as a penalty, and therefore is subject to the five-year statute of limitations.Commission seeking “disgorgement,” or payment, of illegally obtained funds.","sumSrc":"Oyez","by":{"0":"29","2":"2"}},{"t":"case","label":"Litwin v. Blackstone Grp., L.P.","cite":"634 F.3d 706","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/634/706/","by":{"0":"27, 28","1":"3, 4, 8","4":"4"}},{"t":"case","label":"Lorenzo v. Sec. & Exch. Comm’n","cite":"139 S. Ct. 1094","y":2019,"id":"2018/17-1077","sc":1,"sum":"Dissemination of false or misleading statements with intent to defraud can fall within the scope of SEC Rules 10b–5(a) and (c), as well as the relevant statutory provisions, even if the disseminator cannot be held liable under Rule 10b–5(b).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23, 24","2":"18-19, 33-34","3":"20-24, 32, 34","4":"10, 11"}},{"t":"case","label":"Matrixx Initiatives, Inc. v. Siracusano","cite":"563 U.S. 27","y":2011,"id":"2010/09-1156","sc":1,"op":1,"sum":"The Court held that a plaintiff could state a claim based on a pharmaceutical company's non-disclosure of adverse event reports, even though the reports are not alleged to be statistically significant.","sumSrc":"Oyez","by":{"0":"2, 21, 22, 28","2":"4, 22, 26-27, 45, 27","3":"22","4":"7"}},{"t":"case","label":"McCarthy v. Bronson","cite":"500 U.S. 136","y":1991,"id":"1990/90-5635","sc":1,"sum":"Section 636(b)(1)(B) does not, as petitioner contends, permit nonconsensual referrals to a magistrate only when a prisoner challenges ongoing prison conditions, but encompasses cases alleging a specific episode of unconstitutional conduct by prison administrators.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Omnicare, Inc. v. Laborers Dist. Council Constr. Indus. Pension Fund","cite":"575 U.S. 175","y":2015,"id":"2014/13-435","sc":1,"op":2,"ar":1,"sum":"The Court ruled that a statement of opinion, even if shown to be objectively false, cannot constitute an untrue statement of fact because of the different nature between opinions and facts.","sumSrc":"Oyez","by":{"0":"36, 44","2":"16-18, 21, 27-28","3":"10","4":"7, 15, 17, 20, 21"}},{"t":"case","label":"Oran v. Stafford","cite":"226 F.3d 275","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/226/275/","op":1,"by":{"0":"29, 42","2":"42-44","3":"19, 26, 27","4":"21"}},{"t":"case","label":"Panther Partners Inc. v. Ikanos Commc’ns, Inc.","cite":"681 F.3d 114","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/681/114/","by":{"0":"27, 28","1":"3, 8","4":"4"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"viii Salman v. United States","cite":"580 U.S. 39","y":2016,"url":"https://supreme.justia.com/cases/federal/us/580/39/","sc":1,"by":{"0":"23"}},{"t":"case","label":"Santa Fe Indus. v. Green","cite":"430 U.S. 462","y":1977,"id":"1976/75-1753","sc":1,"sum":"Delaware's \"short-form merger\" statute enables a parent company owning at least 90% of the stock of a subsidiary to merge with the subsidiary upon approval of the parent company's board of directors, and to make cash payments for the minority shareholders' shares. Though advance notice to or consent of the minority shareholders is not required, they must be notified within 10 days of the merger's effective date, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","2":"16"}},{"t":"case","label":"Sec. & Exch. Comm’n v. McNulty","cite":"137 F.3d 732","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/137/732/","by":{"0":"8"}},{"t":"case","label":"Sec. & Exch. Comm’n v. Rio Tinto plc","cite":"41 F.4th 47","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/41/47/","by":{"0":"24","4":"11"}},{"t":"case","label":"Sec. & Exch. Comm’n v. Ronson Corp.","cite":"1983 WL 1357","y":1983,"court":"D.N.J. Aug. 15","by":{"0":"45"}},{"t":"case","label":"Sec. & Exch. Comm’n v. Teo","cite":"746 F.3d 90","y":2014,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/746/90/","by":{"0":"8"}},{"t":"case","label":"Slack Techs., LLC v. Pirani","cite":"598 U.S. 759","y":2023,"id":"2022/22-200","sc":1,"sum":"To state a claim under §11(a) of the Securities Act of 1933, a plaintiff must allege the purchase of “such security” issued pursuant to a materially misleading registration statement.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20, 25","2":"2"}},{"t":"case","label":"Stoneridge Inv. Partners, LLC v. Sci.Atl., Inc.","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"op":1,"ar":1,"sum":"The Court held that, under Central Bank and Section 10(b), securities fraud plaintiffs cannot sue \"aiders and abettors\" like Scientific-Atlanta. The Court noted Congress' subsequent failure to create a right of private action against aiders and abettors in the Private Securities Litigation Reform Act for support of its position that no such right should be allowed in the present case.","sumSrc":"Oyez","by":{"0":"2, 8, 20, 22, 31, 38, 39","1":"2","2":"3, 18, 35-36","3":"2, 29, 30","4":"7, 11, 12, 13"}},{"t":"case","label":"Stratte-McClure v. Morgan Stanley","cite":"776 F.3d 94","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/776/94/","op":2,"ar":4,"by":{"0":"14, 28, 35","1":"3, 7, 8","2":"12, 42,44","3":"19, 26, 33","4":"4, 5, 6"}},{"t":"case","label":"Superintendent of Ins. v. Bankers Life & Cas. Co.","cite":"404 U.S. 6","y":1971,"id":"1971/70-60","sc":1,"sum":"Section 10 (b) of the Securities Exchange Act of 1934 makes it unlawful to use \"in connection with the purchase or sale\" of any security \"any manipulative or deceptive device or contrivance\" in contravention of the Securities and Exchange Commission's rules and regulations. Section 10 (b) prohibits the use of any deceptive device in the \"sale\" of any security by \"any person,\" and it is irrelevant that Manhattan was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7"}},{"t":"case","label":"Tellabs, Inc. v. Makor Issues & Rts., Ltd.","cite":"551 U.S. 308","y":2007,"id":"2006/06-484","sc":1,"sum":"The Court ruled by a vote of 8-1 that a securities fraud complaint must allege facts establishing an inference of guilty intent that is \"cogent and at least as compelling as any opposing inference of nonfraudulent intent.\" Justice Ruth Bader Ginsburg wrote that opinion for the Court, which held that the Seventh Circuit's more relaxed standard was not strong enough to comport with Congress's intent in PSLRA to limit securities fraud litigation. \"The strength of an inference cannot be decided in a vacuum.","sumSrc":"Oyez","by":{"0":"8","2":"7, 44-45, 47","3":"5, 28"}},{"t":"case","label":"Touche Ross & Co. v. Redington","cite":"442 U.S. 560","y":1979,"id":"1978/78-309","sc":1,"sum":"There is no implied private cause of action for damages under § 17 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 7, 31, 32","2":"31","3":"32"}},{"t":"case","label":"ix United States v. O’Hagan","cite":"521 U.S. 642","y":1997,"id":"1996/96-842","sc":1,"sum":"The Court ruled that a security-trader who fails to disclose personal profits gained from reliance on exclusive information is guilty of employing \"a deceptive device...in connection with the purchase of a security.\" The security-trader knowingly abuses the duty owed toward the source of information, whether the source is the company he works for or not.","sumSrc":"Oyez","by":{"0":"21, 23","2":"19, 24","3":"19, 21","4":"10"}},{"t":"case","label":"Universal Health Servs. v. United States ex rel. Escobar","cite":"579 U.S. 176","y":2016,"id":"2015/15-7","sc":1,"op":2,"sum":"The Court held that the implied certification test could be a valid basis for False Claims Act liability, and the conditions of payment with which the defendant allegedly failed to comply did not need to be explicitly stated.","sumSrc":"Oyez","by":{"0":"19, 33, 39","2":"17, 22-23, 29, 39-40, 45","3":"10, 11, 14, 15, 17, 18, 29","4":"17, 18"}},{"t":"case","label":"Va. Bankshares, Inc. v. Sandberg","cite":"501 U.S. 1083","y":1991,"id":"1990/89-1448","sc":1,"sum":"Respectively. Terms like \"high value,\" in a commercial context, are reasonably understood to rest on a factual basis, and so could be shown to be misleading by garden-variety evidence. Furthermore, they can be materially misleading even if other information is available in the statement upon which an expert could deduce that they are false. A proxy statement should inform, not challenge the reader's critical wits.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 420","y":2000,"id":"1999/99-6615","sc":1,"sum":"The Court held that under federal law, as amended by the AEDPA, \"a 'failure to develop' a claim's factual basis in state court proceedings is not established unless there is lack of diligence, or some greater fault, attributable to the prisoner or his counsel.\" Justice Kennedy wrote for the Court that \"comity is not served by saying a prisoner 'has failed to develop the factual basis of a claim' where he was unable to develop his claim in state court despite diligent effort.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"usc","label":"15 U.S.C. § 77e","url":"https://www.law.cornell.edu/uscode/text/15/77e","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 77j","url":"https://www.law.cornell.edu/uscode/text/15/77j","subs":["(c)"],"by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 77k","url":"https://www.law.cornell.edu/uscode/text/15/77k","subs":["(a)","(e)"],"stext":{"head":"§77k. Civil liabilities on account of false registration statement","paras":[[0,"(a) Persons possessing cause of action; persons liable"],[0,"In case any part of the registration statement, when such part became effective, contained an untrue statement of a material fact or omitted to state a material fact required to be stated therein or necessary to make the statements therein not misleading, any person acquiring such security (unless it is proved that at the time of such acquisition he knew of such untruth or omission) may, either at law or in equity, in any court of competent jurisdiction, sue—"],[1,"(1) every person who signed the registration statement;"],[1,"(2) every person who was a director of (or person performing similar functions) or partner in the issuer at the time of the filing of the part of the registration statement with respect to which his liability is asserted;"],[1,"(3) every person who, with his consent, is named in the registration statement as being or about to become a director, person performing similar functions, or partner;"],[1,"(4) every accountant, engineer, or appraiser, or any person whose profession gives authority to a statement made by him, who has with his consent been named as having prepared or certified any part of the registration statement, or as having prepared or certified any report or valuation which is used in connection with the registration statement, with respect to the statement in such registration statement, report, or valuation, which purports to have been prepared or certified by him;"],[1,"(5) every underwriter with respect to such security."],[0,"If such person acquired the security after the issuer has made generally available to its security holders an earning statement covering a period of at least twelve months beginning after the effective date of the registration statement, then the right of recovery under this subsection shall be conditioned on proof that such person acquired the security relying upon such untrue statement in the registration statement or relying upon the registration statement and not knowing of such omission, but such reliance may be established without proof of the reading of the registration statement by such person."],[0,"(b) Persons exempt from liability upon proof of issues"],[0,"Notwithstanding the provisions of subsection (a) no person, other than the issuer, shall be liable as provided therein who shall sustain the burden of proof—"],[1,"(1) that before the effective date of the part of the registration statement with respect to which his liability is asserted (A) he had resigned from or had taken such steps as are permitted by law to resign from, or ceased or refused to act in, every office, capacity, or relationship in which he was described in the registration statement as acting or agreeing to act, and (B) he had advised the Commission and the issuer in writing that he had taken such action and that he would not be responsible for such part of the registration statement; or"],[1,"(2) that if such part of the registration statement became effective without his knowledge, upon becoming aware of such fact he forthwith acted and advised the Commission, in accordance with paragraph (1) of this subsection, and, in addition, gave reasonable public notice that such part of the registration statement had become effective without his knowledge; or"],[1,"(3) that (A) as regards any part of the registration statement not purporting to be made on the authority of an expert, and not purporting to be a copy of or extract from a report or valuation of an expert, and not purporting to be made on the authority of a public official document or statement, he had, after reasonable investigation, reasonable ground to believe and did believe, at the time such part of the registration statement became effective, that the statements therein were true and that there was no omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading; and (B) as regards any part of the registration statement purporting to be made upon his authority as an expert or purporting to be a copy of or extract from a report or valuation of himself as an expert, (i) he had, after reasonable investigation, reasonable ground to believe and did believe, at the time such part of the registration statement became effective, that the statements therein were true and that there was no omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or (ii) such part of the registration statement did not fairly represent his statement as an expert or was not a fair copy of or extract from his report or valuation as an expert; and (C) as regards any part of the registration statement purporting to be made on the authority of an expert (other than himself) or purporting to be a copy of or extract from a report or valuation of an expert (other than himself), he had no reasonable ground to believe and did not believe, at the time such part of the registration statement became effective, that the statements therein were untrue or that there was an omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or that such part of the registration statement did not fairly represent the statement of the expert or was not a fair copy of or extract from the report or valuation of the expert; and (D) as regards any part of the registration statement purporting to be a statement made by an official person or purporting to be a copy of or extract from a public official document, he had no reasonable ground to believe and did not believe, at the time such part of the registration statement became effective, that the statements therein were untrue, or that there was an omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or that such part of the registration statement did not fairly represent the statement made by the official person or was not a fair copy of or extract from the public official document."],[0,"(c) Standard of reasonableness"],[0,"In determining, for the purpose of paragraph (3) of subsection (b) of this section, what constitutes reasonable investigation and reasonable ground for belief, the standard of reasonableness shall be that required of a prudent man in the management of his own property."],[0,"(d) Effective date of registration statement with regard to underwriters"],[0,"If any person becomes an underwriter with respect to the security after the part of the registration statement with respect to which his liability is asserted has become effective, then for the purposes of paragraph (3) of subsection (b) of this section such part of the registration statement shall be considered as having become effective with respect to such person as of the time when he became an underwriter."],[0,"(e) Measure of damages; undertaking for payment of costs"],[0,"The suit authorized under subsection (a) may be to recover such damages as shall represent the difference between the amount paid for the security (not exceeding the price at which the security was offered to the public) and (1) the value thereof as of the time such suit was brought, or (2) the price at which such security shall have been disposed of in the market before suit, or (3) the price at which such security shall have been disposed of after suit but before judgment if such damages shall be less than the damages representing the difference between the amount paid for the security (not exceeding the price at which the security was offered to the public) and the value thereof as of the time such suit was brought: Provided, That if the defendant proves that any portion or all of such damages represents other than the depreciation in value of such security resulting from such part of the registration statement, with respect to which his liability is asserted, not being true or omitting to state a material fact required to be stated therein or necessary to make the statements therein not misleading, such portion of or all such damages shall not be recoverable. In no event shall any underwriter (unless such underwriter shall have knowingly received from the issuer for acting as an underwriter some benefit, directly or indirectly, in which all other underwriters similarly situated did not share in proportion to their respective interests in the underwriting) be liable in any suit or as a consequence of suits authorized under subsection (a) for damages in excess of the total price at which the securities underwritten by him and distributed to the public were offered to the public. In any suit under this or any other section of this subchapter the court may, in its discretion, require an undertaking for the payment of the costs of such suit, including reasonable attorney's fees, and if judgment shall be rendered against a party litigant, upon the motion of the other party litigant, such costs may be assessed in favor of such party litigant (whether or not such undertaking has been required) if the court believes the suit or the defense to have been without merit, in an amount sufficient to reimburse him for the reasonable expenses incurred by him, in connection with such suit, such costs to be taxed in the manner usually provided for taxing of costs in the court in which the suit was heard."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77k?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§77k. Civil liabilities on account of false registration statement","tname":"Commerce and Trade","by":{"0":"1, 5, 13, 17, 18, 26, 27, 28, 34, 27","2":"11, 14, 21, 27, 30-33, 43-44, 48-49, 27, 30, 33","3":"30, 31","4":"4, 5, 6, 7, 8, 4, 5"}},{"t":"usc","label":"15 U.S.C. § 77l","url":"https://www.law.cornell.edu/uscode/text/15/77l","subs":["(a)(2)","(b)"],"stext":{"head":"§77l. Civil liabilities arising in connection with prospectuses and communications","paras":[[0,"(a) In general"],[0,"Any person who—"],[1,"(1) offers or sells a security in violation of section 77e of this title, or"],[1,"(2) offers or sells a security (whether or not exempted by the provisions of section 77c of this title, other than paragraphs (2) and (14) of subsection (a) of said section), by the use of any means or instruments of transportation or communication in interstate commerce or of the mails, by means of a prospectus or oral communication, which includes an untrue statement of a material fact or omits to state a material fact necessary in order to make the statements, in the light of the circumstances under which they were made, not misleading (the purchaser not knowing of such untruth or omission), and who shall not sustain the burden of proof that he did not know, and in the exercise of reasonable care could not have known, of such untruth or omission,"],[0,"shall be liable, subject to subsection (b), to the person purchasing such security from him, who may sue either at law or in equity in any court of competent jurisdiction, to recover the consideration paid for such security with interest thereon, less the amount of any income received thereon, upon the tender of such security, or for damages if he no longer owns the security."],[0,"(b) Loss causation"],[0,"In an action described in subsection (a)(2), if the person who offered or sold such security proves that any portion or all of the amount recoverable under subsection (a)(2) represents other than the depreciation in value of the subject security resulting from such part of the prospectus or oral communication, with respect to which the liability of that person is asserted, not being true or omitting to state a material fact required to be stated therein or necessary to make the statement not misleading, then such portion or amount, as the case may be, shall not be recoverable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77l?type=usc&year=mostrecent&link-type=html"},"head":"§77l. Civil liabilities arising in connection with prospectuses and communications","tname":"Commerce and Trade","by":{"0":"5, 13, 27, 5, 27","2":"33, 49, 11, 33, 48-49, 33","4":"4, 5, 4, 5"}},{"t":"usc","label":"15 U.S.C. § 77o","url":"https://www.law.cornell.edu/uscode/text/15/77o","by":{"0":"5, 13"}},{"t":"usc","label":"15 U.S.C. § 78d","url":"https://www.law.cornell.edu/uscode/text/15/78d","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§78j. Manipulative and deceptive devices","tname":"Commerce and Trade","by":{"0":"1, 4, 5, 6, 7, 20, 21, 22, 25, 26, 27, 29, 31, 38","2":"21, 31, 49, 1-4, 11-16, 24, 28, 30-31, 35-37, 41-47","3":"3","4":"6, 7, 8, 17"}},{"t":"usc","label":"15 U.S.C. § 78m","url":"https://www.law.cornell.edu/uscode/text/15/78m","subs":["(a)","(a)(2)","(a)(1)"],"stext":{"head":"§78m. Periodical and other reports","paras":[[0,"(a) Reports by issuer of security; contents"],[0,"Every issuer of a security registered pursuant to section 78l of this title shall file with the Commission, in accordance with such rules and regulations as the Commission may prescribe as necessary or appropriate for the proper protection of investors and to insure fair dealing in the security—"],[1,"(1) such information and documents (and such copies thereof) as the Commission shall require to keep reasonably current the information and documents required to be included in or filed with an application or registration statement filed pursuant to section 78l of this title, except that the Commission may not require the filing of any material contract wholly executed before July 1, 1962."],[1,"(2) such annual reports (and such copies thereof), certified if required by the rules and regulations of the Commission by independent public accountants, and such quarterly reports (and such copies thereof), as the Commission may prescribe."],[0,"Every issuer of a security registered on a national securities exchange shall also file a duplicate original of such information, documents, and reports with the exchange. In any registration statement, periodic report, or other reports to be filed with the Commission, an emerging growth company need not present selected financial data in accordance with section 229.301 of title 17, Code of Federal Regulations, for any period prior to the earliest audited period presented in connection with its first registration statement that became effective under this chapter or the Securities Act of 1933 [15 U.S.C. 77a et seq.] and, with respect to any such statement or reports, an emerging growth company may not be required to comply with any new or revised financial accounting standard until such date that a company that is not an issuer (as defined under section 7201 of this title) is required to comply with such new or revised accounting standard, if such standard applies to companies that are not issuers."],[0,"(b) Form of report; books, records, and internal accounting; directives"],[0,"(1) The Commission may prescribe, in regard to reports made pursuant to this chapter, the form or forms in which the required information shall be set forth, the items or details to be shown in the balance sheet and the earnings statement, and the methods to be followed in the preparation of reports, in the appraisal or valuation of assets and liabilities, in the determination of depreciation and depletion, in the differentiation of recurring and nonrecurring income, in the differentiation of investment and operating income, and in the preparation, where the Commission deems it necessary or desirable, of separate and/or consolidated balance sheets or income accounts of any person directly or indirectly controlling or controlled by the issuer, or any person under direct or indirect common control with the issuer; but in the case of the reports of any person whose methods of accounting are prescribed under the provisions of any law of the United States, or any rule or regulation thereunder, the rules and regulations of the Commission with respect to reports shall not be inconsistent with the requirements imposed by such law or rule or regulation in respect of the same subject matter (except that such rules and regulations of the Commission may be inconsistent with such requirements to the extent that the Commission determines that the public interest or the protection of investors so requires)."],[0,"(2) Every issuer which has a class of securities registered pursuant to section 78l of this title and every issuer which is required to file reports pursuant to section 78o(d) of this title shall—"],[1,"(A) make and keep books, records, and accounts, which, in reasonable detail, accurately and fairly reflect the transactions and dispositions of the assets of the issuer;"],[1,"(B) devise and maintain a system of internal accounting controls sufficient to provide reasonable assurances that—"],[2,"(i) transactions are executed in accordance with management's general or specific authorization;"],[2,"(ii) transactions are recorded as necessary (I) to permit preparation of financial statements in conformity with generally accepted accounting principles or any other criteria applicable to such statements, and (II) to maintain accountability for assets;"],[2,"(iii) access to assets is permitted only in accordance with management's general or specific authorization; and"],[2,"(iv) the recorded accountability for assets is compared with the existing assets at reasonable intervals and appropriate action is taken with respect to any differences; and"],[1,"(C) notwithstanding any other provision of law, pay the allocable share of such issuer of a reasonable annual accounting support fee or fees, determined in accordance with section 7219 of this title."],[0,"(3)(A) With respect to matters concerning the national security of the United States, no duty or liability under paragraph (2) of this subsection shall be imposed upon any person acting in cooperation with the head of any Federal department or agency responsible for such matters if such act in cooperation with such head of a department or agency was done upon the specific, written directive of the head of such department or agency pursuant to Presidential authority to issue such directives. Each directive issued under this paragraph shall set forth the specific facts and circumstances with respect to which the provisions of this paragraph are to be invoked. Each such directive shall, unless renewed in writing, expire one year after the date of issuance."],[0,"(B) Each head of a Federal department or agency of the United States who issues a directive pursuant to this paragraph shall maintain a complete file of all such directives and shall, on October 1 of each year, transmit a summary of matters covered by such directives in force at any time during the previous year to the Permanent Select Committee on Intelligence of the House of Representatives and the Select Committee on Intelligence of the Senate."],[0,"(4) No criminal liability shall be imposed for failing to comply with the requirements of paragraph (2) of this subsection except as provided in paragraph (5) of this subsection."],[0,"(5) No person shall knowingly circumvent or knowingly fail to implement a system of internal accounting controls or knowingly falsify any book, record, or account described in paragraph (2)."],[0,"(6) Where an issuer which has a class of securities registered pursuant to section 78l of this title or an issuer which is required to file reports pursuant to section 78o(d) of this title holds 50 per centum or less of the voting power with respect to a domestic or foreign firm, the provisions of paragraph (2) require only that the issuer proceed in good faith to use its influence, to the extent reasonable under the issuer's circumstances, to cause such domestic or foreign firm to devise and maintain a system of internal accounting controls consistent with paragraph (2). Such circumstances include the relative degree of the issuer's ownership of the domestic or foreign firm and the laws and practices governing the business operations of the country in which such firm is located. An issuer which demonstrates good faith efforts to use such influence shall be conclusively presumed to have complied with the requirements of paragraph (2)."],[0,"(7) For the purpose of paragraph (2) of this subsection, the terms \"reasonable assurances\" and \"reasonable detail\" mean such level of detail and degree of assurance as would satisfy prudent officials in the conduct of their own affairs."],[0,"(c) Alternative reports"],[0,"If in the judgment of the Commission any report required under subsection (a) is inapplicable to any specified class or classes of issuers, the Commission shall require in lieu thereof the submission of such reports of comparable character as it may deem applicable to such class or classes of issuers."],[0,"(d) Reports by persons acquiring more than five per centum of certain classes of securities"],[0,"(1) Any person who, after acquiring directly or indirectly the beneficial ownership of any equity security of a class which is registered pursuant to section 78l of this title, or any equity security of an insurance company which would have been required to be so registered except for the exemption contained in section 78l(g)(2)(G) of this title, or any equity security issued by a closed-end investment company registered under the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.] or any equity security issued by a Native Corporation pursuant to section 1629c(d)(6) of title 43, or otherwise becomes or is deemed to become a beneficial owner of any of the foregoing upon the purchase or sale of a security-based swap that the Commission may define by rule, and is directly or indirectly the beneficial owner of more than 5 per centum of such class shall, within ten days after such acquisition or within such shorter time as the Commission may establish by rule, file with the Commission, a statement containing such of the following information, and such additional information, as the Commission may by rules and regulations, prescribe as necessary or appropriate in the public interest or for the protection of investors—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78m?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§78m. Periodical and other reports","tname":"Commerce and Trade","by":{"0":"5, 6, 8, 16, 35","2":"4, 17, 20, 26, 39, 41, 9, 16-17, 29, 39, 46, 4, 39","3":"2, 3, 5, 12, 3","4":"9, 15"}},{"t":"usc","label":"15 U.S.C. § 78r","url":"https://www.law.cornell.edu/uscode/text/15/78r","subs":["(a)"],"stext":{"head":"§78r. Liability for misleading statements","paras":[[0,"(a) Persons liable; persons entitled to recover; defense of good faith; suit at law or in equity; costs, etc."],[0,"Any person who shall make or cause to be made any statement in any application, report, or document filed pursuant to this chapter or any rule or regulation thereunder or any undertaking contained in a registration statement as provided in subsection (d) of section 78o of this title, which statement was at the time and in the light of the circumstances under which it was made false or misleading with respect to any material fact, shall be liable to any person (not knowing that such statement was false or misleading) who, in reliance upon such statement, shall have purchased or sold a security at a price which was affected by such statement, for damages caused by such reliance, unless the person sued shall prove that he acted in good faith and had no knowledge that such statement was false or misleading. A person seeking to enforce such liability may sue at law or in equity in any court of competent jurisdiction. In any such suit the court may, in its discretion, require an undertaking for the payment of the costs of such suit, and assess reasonable costs, including reasonable attorneys' fees, against either party litigant."],[0,"(b) Contribution"],[0,"Every person who becomes liable to make payment under this section may recover contribution as in cases of contract from any person who, if joined in the original suit, would have been liable to make the same payment."],[0,"(c) Period of limitations"],[0,"No action shall be maintained to enforce any liability created under this section unless brought within one year after the discovery of the facts constituting the cause of action and within three years after such cause of action accrued."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78r?type=usc&year=mostrecent&link-type=html"},"head":"§78r. Liability for misleading statements","tname":"Commerce and Trade","by":{"0":"5, 17, 6, 17, 25, 30, 31","2":"31","3":"32, 32","4":"8"}},{"t":"usc","label":"15 U.S.C. § 78t","url":"https://www.law.cornell.edu/uscode/text/15/78t","subs":["(a)"],"by":{"0":"5, 13"}},{"t":"usc","label":"15 U.S.C. § 78t-1","url":"https://www.law.cornell.edu/uscode/text/15/78t-1","stext":{"head":"§78t–1. Liability to contemporaneous traders for insider trading","paras":[[0,"(a) Private rights of action based on contemporaneous trading"],[0,"Any person who violates any provision of this chapter or the rules or regulations thereunder by purchasing or selling a security while in possession of material, nonpublic information shall be liable in an action in any court of competent jurisdiction to any person who, contemporaneously with the purchase or sale of securities that is the subject of such violation, has purchased (where such violation is based on a sale of securities) or sold (where such violation is based on a purchase of securities) securities of the same class."],[0,"(b) Limitations on liability"],[0,"(1) Contemporaneous trading actions limited to profit gained or loss avoided"],[1,"The total amount of damages imposed under subsection (a) shall not exceed the profit gained or loss avoided in the transaction or transactions that are the subject of the violation."],[0,"(2) Offsetting disgorgements against liability"],[1,"The total amount of damages imposed against any person under subsection (a) shall be diminished by the amounts, if any, that such person may be required to disgorge, pursuant to a court order obtained at the instance of the Commission, in a proceeding brought under section 78u(d) of this title relating to the same transaction or transactions."],[0,"(3) Controlling person liability"],[1,"No person shall be liable under this section solely by reason of employing another person who is liable under this section, but the liability of a controlling person under this section shall be subject to section 78t(a) of this title."],[0,"(4) Statute of limitations"],[1,"No action may be brought under this section more than 5 years after the date of the last transaction that is the subject of the violation."],[0,"(c) Joint and several liability for communicating"],[0,"Any person who violates any provision of this chapter or the rules or regulations thereunder by communicating material, nonpublic information shall be jointly and severally liable under subsection (a) with, and to the same extent as, any person or persons liable under subsection (a) to whom the communication was directed."],[0,"(d) Authority not to restrict other express or implied rights of action"],[0,"Nothing in this section shall be construed to limit or condition the right of any person to bring an action to enforce a requirement of this chapter or the availability of any cause of action implied from a provision of this chapter."],[0,"(e) Provisions not to affect public prosecutions"],[0,"This section shall not be construed to bar or limit in any manner any action by the Commission or the Attorney General under any other provision of this chapter, nor shall it bar or limit in any manner any action to recover penalties, or to seek any other order regarding penalties."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78t-1?type=usc&year=mostrecent&link-type=html"},"head":"§78t–1. Liability to contemporaneous traders for insider trading","tname":"Commerce and Trade","by":{"0":"5, 13","2":"11"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","subs":["(a)(1)","(d)(1)","(d)(3)","(d)(5)","(d)(7)","(d)(2)"],"stext":{"head":"§78u. Investigations and actions","paras":[[0,"(a) Authority and discretion of Commission to investigate violations"],[0,"(1) The Commission may, in its discretion, make such investigations as it deems necessary to determine whether any person has violated, is violating, or is about to violate any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated, or, as to any act or practice, or omission to act, while associated with a member, formerly associated with a member, the rules of a registered clearing agency in which such person is a participant, or, as to any act or practice, or omission to act, while a participant, was a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm, a person associated with such a firm, or, as to any act, practice, or omission to act, while associated with such firm, a person formerly associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, and may require or permit any person to file with it a statement in writing, under oath or otherwise as the Commission shall determine, as to all the facts and circumstances concerning the matter to be investigated. The Commission is authorized in its discretion, to publish information concerning any such violations, and to investigate any facts, conditions, practices, or matters which it may deem necessary or proper to aid in the enforcement of such provisions, in the prescribing of rules and regulations under this chapter, or in securing information to serve as a basis for recommending further legislation concerning the matters to which this chapter relates."],[0,"(2) On request from a foreign securities authority, the Commission may provide assistance in accordance with this paragraph if the requesting authority states that the requesting authority is conducting an investigation which it deems necessary to determine whether any person has violated, is violating, or is about to violate any laws or rules relating to securities matters that the requesting authority administers or enforces. The Commission may, in its discretion, conduct such investigation as the Commission deems necessary to collect information and evidence pertinent to the request for assistance. Such assistance may be provided without regard to whether the facts stated in the request would also constitute a violation of the laws of the United States. In deciding whether to provide such assistance, the Commission shall consider whether (A) the requesting authority has agreed to provide reciprocal assistance in securities matters to the Commission; and (B) compliance with the request would prejudice the public interest of the United States."],[0,"(b) Attendance of witnesses; production of records"],[0,"For the purpose of any such investigation, or any other proceeding under this chapter, any member of the Commission or any officer designated by it is empowered to administer oaths and affirmations, subpena witnesses, compel their attendance, take evidence, and require the production of any books, papers, correspondence, memoranda, or other records which the Commission deems relevant or material to the inquiry. Such attendance of witnesses and the production of any such records may be required from any place in the United States or any State at any designated place of hearing."],[0,"(c) Judicial enforcement of investigative power of Commission; refusal to obey subpena; criminal sanctions"],[0,"In case of contumacy by, or refusal to obey a subpena issued to, any person, the Commission may invoke the aid of any court of the United States within the jurisdiction of which such investigation or proceeding is carried on, or where such person resides or carries on business, in requiring the attendance and testimony of witnesses and the production of books, papers, correspondence, memoranda, and other records. And such court may issue an order requiring such person to appear before the Commission or member or officer designated by the Commission, there to produce records, if so ordered, or to give testimony touching the matter under investigation or in question; and any failure to obey such order of the court may be punished by such court as a contempt thereof. All process in any such case may be served in the judicial district whereof such person is an inhabitant or wherever he may be found. Any person who shall, without just cause, fail or refuse to attend and testify or to answer any lawful inquiry or to produce books, papers, correspondence, memoranda, and other records, if in his power so to do, in obedience to the subpena of the Commission, shall be guilty of a misdemeanor and, upon conviction, shall be subject to a fine of not more than $1,000 or to imprisonment for a term of not more than one year, or both."],[0,"(d) Injunction proceedings; authority of court to prohibit persons from serving as officers and directors; money penalties in civil actions; disgorgement"],[0,"(1) Whenever it shall appear to the Commission that any person is engaged or is about to engage in acts or practices constituting a violation of any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated with a member, the rules of a registered clearing agency in which such person is a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm or a person associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, it may in its discretion bring an action in the proper district court of the United States, the United States District Court for the District of Columbia, or the United States courts of any territory or other place subject to the jurisdiction of the United States, to enjoin such acts or practices, and upon a proper showing a permanent or temporary injunction or restraining order shall be granted without bond. The Commission may transmit such evidence as may be available concerning such acts or practices as may constitute a violation of any provision of this chapter or the rules or regulations thereunder to the Attorney General, who may, in his discretion, institute the necessary criminal proceedings under this chapter."],[0,"(2) Authority of Court To Prohibit Persons From Serving as Officers and Directors.—In any proceeding under paragraph (1) of this subsection, the court may prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who violated section 78j(b) of this title or the rules or regulations thereunder from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title or that is required to file reports pursuant to section 78o(d) of this title if the person's conduct demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(3) Civil money penalties and authority to seek disgorgement.—"],[1,"(A) Authority of commission.—Whenever it shall appear to the Commission that any person has violated any provision of this chapter, the rules or regulations thereunder, or a cease-and-desist order entered by the Commission pursuant to section 78u–3 of this title, other than by committing a violation subject to a penalty pursuant to section 78u–1 of this title, the Commission may bring an action in a United States district court to seek, and the court shall have jurisdiction to—"],[2,"(i) impose, upon a proper showing, a civil penalty to be paid by the person who committed such violation; and"],[2,"(ii) require disgorgement under paragraph (7) of any unjust enrichment by the person who received such unjust enrichment as a result of such violation."],[1,"(B) Amount of penalty.—"],[2,"(i) First tier.—The amount of a civil penalty imposed under subparagraph (A)(i) shall be determined by the court in light of the facts and circumstances. For each violation, the amount of the penalty shall not exceed the greater of (I) $5,000 for a natural person or $50,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation."],[2,"(ii) Second tier.—Notwithstanding clause (i), the amount of a civil penalty imposed under subparagraph (A)(i) for each such violation shall not exceed the greater of (I) $50,000 for a natural person or $250,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if the violation described in subparagraph (A) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[2,"(iii) Third tier.—Notwithstanding clauses (i) and (ii), the amount of a civil penalty imposed under subparagraph (A)(i) for each violation described in that subparagraph shall not exceed the greater of (I) $100,000 for a natural person or $500,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u?type=usc&year=mostrecent&link-type=html"},"head":"§78u. Investigations and actions","tname":"Commerce and Trade","by":{"0":"29, 29, 30, 30, 30, 30","3":"33"}},{"t":"usc","label":"15 U.S.C. § 78u-2","url":"https://www.law.cornell.edu/uscode/text/15/78u-2","subs":["(a)(2)"],"stext":{"head":"§78u–2. Civil remedies in administrative proceedings","paras":[[0,"(a) Commission authority to assess money penalties"],[0,"(1) In general"],[1,"In any proceeding instituted pursuant to sections 78o(b)(4), 78o(b)(6), 78o–6, 78o–4, 78o–5, 78o–7, or 78q–1 of this title against any person, the Commission or the appropriate regulatory agency may impose a civil penalty if it finds, on the record after notice and opportunity for hearing, that such penalty is in the public interest and that such person—"],[2,"(A) has willfully violated any provision of the Securities Act of 1933 [15 U.S.C. 77a et seq.], the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.], the Investment Advisers Act of 1940 [15 U.S.C. 80b–1 et seq.], or this chapter, or the rules or regulations thereunder, or the rules of the Municipal Securities Rulemaking Board;"],[2,"(B) has willfully aided, abetted, counseled, commanded, induced, or procured such a violation by any other person;"],[2,"(C) has willfully made or caused to be made in any application for registration or report required to be filed with the Commission or with any other appropriate regulatory agency under this chapter, or in any proceeding before the Commission with respect to registration, any statement which was, at the time and in the light of the circumstances under which it was made, false or misleading with respect to any material fact, or has omitted to state in any such application or report any material fact which is required to be stated therein; or"],[2,"(D) has failed reasonably to supervise, within the meaning of section 78o(b)(4)(E) of this title, with a view to preventing violations of the provisions of such statutes, rules and regulations, another person who commits such a violation, if such other person is subject to his supervision; 1"],[0,"(2) Cease-and-desist proceedings"],[1,"In any proceeding instituted under section 78u–3 of this title against any person, the Commission may impose a civil penalty, if the Commission finds, on the record after notice and opportunity for hearing, that such person—"],[2,"(A) is violating or has violated any provision of this chapter, or any rule or regulation issued under this chapter; or"],[2,"(B) is or was a cause of the violation of any provision of this chapter, or any rule or regulation issued under this chapter."],[0,"(b) Maximum amount of penalty"],[0,"(1) First tier"],[1,"The maximum amount of penalty for each act or omission described in subsection (a) shall be $5,000 for a natural person or $50,000 for any other person."],[0,"(2) Second tier"],[1,"Notwithstanding paragraph (1), the maximum amount of penalty for each such act or omission shall be $50,000 for a natural person or $250,000 for any other person if the act or omission described in subsection (a) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[0,"(3) Third tier"],[1,"Notwithstanding paragraphs (1) and (2), the maximum amount of penalty for each such act or omission shall be $100,000 for a natural person or $500,000 for any other person if—"],[2,"(A) the act or omission described in subsection (a) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement; and"],[2,"(B) such act or omission directly or indirectly resulted in substantial losses or created a significant risk of substantial losses to other persons or resulted in substantial pecuniary gain to the person who committed the act or omission."],[0,"(c) Determination of public interest"],[0,"In considering under this section whether a penalty is in the public interest, the Commission or the appropriate regulatory agency may consider—"],[1,"(1) whether the act or omission for which such penalty is assessed involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement;"],[1,"(2) the harm to other persons resulting either directly or indirectly from such act or omission;"],[1,"(3) the extent to which any person was unjustly enriched, taking into account any restitution made to persons injured by such behavior;"],[1,"(4) whether such person previously has been found by the Commission, another appropriate regulatory agency, or a self-regulatory organization to have violated the Federal securities laws, State securities laws, or the rules of a self-regulatory organization, has been enjoined by a court of competent jurisdiction from violations of such laws or rules, or has been convicted by a court of competent jurisdiction of violations of such laws or of any felony or misdemeanor described in section 78o(b)(4)(B) of this title;"],[1,"(5) the need to deter such person and other persons from committing such acts or omissions; and"],[1,"(6) such other matters as justice may require."],[0,"(d) Evidence concerning ability to pay"],[0,"In any proceeding in which the Commission or the appropriate regulatory agency may impose a penalty under this section, a respondent may present evidence of the respondent's ability to pay such penalty. The Commission or the appropriate regulatory agency may, in its discretion, consider such evidence in determining whether such penalty is in the public interest. Such evidence may relate to the extent of such person's ability to continue in business and the collectability of a penalty, taking into account any other claims of the United States or third parties upon such person's assets and the amount of such person's assets."],[0,"(e) Authority to enter order requiring accounting and disgorgement"],[0,"In any proceeding in which the Commission or the appropriate regulatory agency may impose a penalty under this section, the Commission or the appropriate regulatory agency may enter an order requiring accounting and disgorgement, including reasonable interest. The Commission is authorized to adopt rules, regulations, and orders concerning payments to investors, rates of interest, periods of accrual, and such other matters as it deems appropriate to implement this subsection."],[0,"(f) Security-based swaps"],[0,"(1) Clearing agency"],[1,"Any clearing agency that knowingly or recklessly evades or participates in or facilitates an evasion of the requirements of section 78c–3 of this title shall be liable for a civil money penalty in twice the amount otherwise available for a violation of section 78c–3 of this title."],[0,"(2) Security-based swap dealer or major security-based swap participant"],[1,"Any security-based swap dealer or major security-based swap participant that knowingly or recklessly evades or participates in or facilitates an evasion of the requirements of section 78c–3 of this title shall be liable for a civil money penalty in twice the amount otherwise available for a violation of section 78c–3 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u-2?type=usc&year=mostrecent&link-type=html"},"head":"§78u–2. Civil remedies in administrative proceedings","tname":"Commerce and Trade","by":{"0":"8","3":"3, 33"}},{"t":"usc","label":"15 U.S.C. § 78u-3","url":"https://www.law.cornell.edu/uscode/text/15/78u-3","subs":["(a)"],"by":{"0":"8"}},{"t":"law","label":"Pub. L. No. 104-67","url":"https://www.govinfo.gov/link/plaw/104/public/67","by":{"0":"2, 5, 7, 8, 18, 31, 32, 38","2":"3, 14, 29, 33, 35-38, 45","3":"16","4":"5"}},{"t":"usc","label":"15 U.S.C. § 78u-4","url":"https://www.law.cornell.edu/uscode/text/15/78u-4","subs":["(b)(1)","(b)(3)(A)","(b)(4)","(b)(2)","(f)(10)(A)(i)","(b)(2)(A)","(f)(10)(A)(i)(I)","(f)(10)(A)(ii)"],"stext":{"head":"§78u–4. Private securities litigation","paras":[[0,"(a) Private class actions"],[0,"(1) In general"],[1,"The provisions of this subsection shall apply in each private action arising under this chapter that is brought as a plaintiff class action pursuant to the Federal Rules of Civil Procedure."],[0,"(2) Certification filed with complaint"],[0,"(A) In general"],[2,"Each plaintiff seeking to serve as a representative party on behalf of a class shall provide a sworn certification, which shall be personally signed by such plaintiff and filed with the complaint, that—"],[3,"(i) states that the plaintiff has reviewed the complaint and authorized its filing;"],[3,"(ii) states that the plaintiff did not purchase the security that is the subject of the complaint at the direction of plaintiff's counsel or in order to participate in any private action arising under this chapter;"],[3,"(iii) states that the plaintiff is willing to serve as a representative party on behalf of a class, including providing testimony at deposition and trial, if necessary;"],[3,"(iv) sets forth all of the transactions of the plaintiff in the security that is the subject of the complaint during the class period specified in the complaint;"],[3,"(v) identifies any other action under this chapter, filed during the 3-year period preceding the date on which the certification is signed by the plaintiff, in which the plaintiff has sought to serve as a representative party on behalf of a class; and"],[3,"(vi) states that the plaintiff will not accept any payment for serving as a representative party on behalf of a class beyond the plaintiff's pro rata share of any recovery, except as ordered or approved by the court in accordance with paragraph (4)."],[0,"(B) Nonwaiver of attorney-client privilege"],[2,"The certification filed pursuant to subparagraph (A) shall not be construed to be a waiver of the attorney-client privilege."],[0,"(3) Appointment of lead plaintiff"],[0,"(A) Early notice to class members"],[0,"(i) In general"],[3,"Not later than 20 days after the date on which the complaint is filed, the plaintiff or plaintiffs shall cause to be published, in a widely circulated national business-oriented publication or wire service, a notice advising members of the purported plaintiff class—"],[4,"(I) of the pendency of the action, the claims asserted therein, and the purported class period; and"],[4,"(II) that, not later than 60 days after the date on which the notice is published, any member of the purported class may move the court to serve as lead plaintiff of the purported class."],[0,"(ii) Multiple actions"],[3,"If more than one action on behalf of a class asserting substantially the same claim or claims arising under this chapter is filed, only the plaintiff or plaintiffs in the first filed action shall be required to cause notice to be published in accordance with clause (i)."],[0,"(iii) Additional notices may be required under Federal rules"],[3,"Notice required under clause (i) shall be in addition to any notice required pursuant to the Federal Rules of Civil Procedure."],[0,"(B) Appointment of lead plaintiff"],[0,"(i) In general"],[3,"Not later than 90 days after the date on which a notice is published under subparagraph (A)(i), the court shall consider any motion made by a purported class member in response to the notice, including any motion by a class member who is not individually named as a plaintiff in the complaint or complaints, and shall appoint as lead plaintiff the member or members of the purported plaintiff class that the court determines to be most capable of adequately representing the interests of class members (hereafter in this paragraph referred to as the \"most adequate plaintiff\") in accordance with this subparagraph."],[0,"(ii) Consolidated actions"],[3,"If more than one action on behalf of a class asserting substantially the same claim or claims arising under this chapter has been filed, and any party has sought to consolidate those actions for pretrial purposes or for trial, the court shall not make the determination required by clause (i) until after the decision on the motion to consolidate is rendered. As soon as practicable after such decision is rendered, the court shall appoint the most adequate plaintiff as lead plaintiff for the consolidated actions in accordance with this paragraph."],[0,"(iii) Rebuttable presumption"],[0,"(I) In general"],[4,"Subject to subclause (II), for purposes of clause (i), the court shall adopt a presumption that the most adequate plaintiff in any private action arising under this chapter is the person or group of persons that—"],[5,"(aa) has either filed the complaint or made a motion in response to a notice under subparagraph (A)(i);"],[5,"(bb) in the determination of the court, has the largest financial interest in the relief sought by the class; and"],[5,"(cc) otherwise satisfies the requirements of Rule 23 of the Federal Rules of Civil Procedure."],[0,"(II) Rebuttal evidence"],[4,"The presumption described in subclause (I) may be rebutted only upon proof by a member of the purported plaintiff class that the presumptively most adequate plaintiff—"],[5,"(aa) will not fairly and adequately protect the interests of the class; or"],[5,"(bb) is subject to unique defenses that render such plaintiff incapable of adequately representing the class."],[0,"(iv) Discovery"],[3,"For purposes of this subparagraph, discovery relating to whether a member or members of the purported plaintiff class is the most adequate plaintiff may be conducted by a plaintiff only if the plaintiff first demonstrates a reasonable basis for a finding that the presumptively most adequate plaintiff is incapable of adequately representing the class."],[0,"(v) Selection of lead counsel"],[3,"The most adequate plaintiff shall, subject to the approval of the court, select and retain counsel to represent the class."],[0,"(vi) Restrictions on professional plaintiffs"],[3,"Except as the court may otherwise permit, consistent with the purposes of this section, a person may be a lead plaintiff, or an officer, director, or fiduciary of a lead plaintiff, in no more than 5 securities class actions brought as plaintiff class actions pursuant to the Federal Rules of Civil Procedure during any 3-year period."],[0,"(4) Recovery by plaintiffs"],[1,"The share of any final judgment or of any settlement that is awarded to a representative party serving on behalf of a class shall be equal, on a per share basis, to the portion of the final judgment or settlement awarded to all other members of the class. Nothing in this paragraph shall be construed to limit the award of reasonable costs and expenses (including lost wages) directly relating to the representation of the class to any representative party serving on behalf of a class."],[0,"(5) Restrictions on settlements under seal"],[1,"The terms and provisions of any settlement agreement of a class action shall not be filed under seal, except that on motion of any party to the settlement, the court may order filing under seal for those portions of a settlement agreement as to which good cause is shown for such filing under seal. For purposes of this paragraph, good cause shall exist only if publication of a term or provision of a settlement agreement would cause direct and substantial harm to any party."],[0,"(6) Restrictions on payment of attorneys' fees and expenses"],[1,"Total attorneys' fees and expenses awarded by the court to counsel for the plaintiff class shall not exceed a reasonable percentage of the amount of any damages and prejudgment interest actually paid to the class."],[0,"(7) Disclosure of settlement terms to class members"],[1,"Any proposed or final settlement agreement that is published or otherwise disseminated to the class shall include each of the following statements, along with a cover page summarizing the information contained in such statements:"],[0,"(A) Statement of plaintiff recovery"],[2,"The amount of the settlement proposed to be distributed to the parties to the action, determined in the aggregate and on an average per share basis."],[0,"(B) Statement of potential outcome of case"],[0,"(i) Agreement on amount of damages"],[3,"If the settling parties agree on the average amount of damages per share that would be recoverable if the plaintiff prevailed on each claim alleged under this chapter, a statement concerning the average amount of such potential damages per share."],[0,"(ii) Disagreement on amount of damages"],[3,"If the parties do not agree on the average amount of damages per share that would be recoverable if the plaintiff prevailed on each claim alleged under this chapter, a statement from each settling party concerning the issue or issues on which the parties disagree."],[0,"(iii) Inadmissibility for certain purposes"],[3,"A statement made in accordance with clause (i) or (ii) concerning the amount of damages shall not be admissible in any Federal or State judicial action or administrative proceeding, other than an action or proceeding arising out of such statement."],[0,"(C) Statement of attorneys' fees or costs sought"],[2,"If any of the settling parties or their counsel intend to apply to the court for an award of attorneys' fees or costs from any fund established as part of the settlement, a statement indicating which parties or counsel intend to make such an application, the amount of fees and costs that will be sought (including the amount of such fees and costs determined on an average per share basis), and a brief explanation supporting the fees and costs sought. Such information shall be clearly summarized on the cover page of any notice to a party of any proposed or final settlement agreement."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u-4?type=usc&year=mostrecent&link-type=html"},"head":"§78u–4. Private securities litigation","tname":"Commerce and Trade","by":{"0":"5, 38, 18, 32, 36, 33, 37","2":"37, 40, 45, 38, 38, 38, 37, 40, 45, 38, 38, 38","3":"16, 28","4":"13, 14, 19, 5, 6, 14, 10"}},{"t":"usc","label":"18 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/18/1350","subs":["(b)"],"stext":{"head":"§1350. Failure of corporate officers to certify financial reports","paras":[[0,"(a) Certification of Periodic Financial Reports.—Each periodic report containing financial statements filed by an issuer with the Securities Exchange Commission pursuant to section 13(a) or 15(d) of the Securities Exchange Act of 1934 (15 U.S.C. 78m(a) or 78o(d)) shall be accompanied by a written statement by the chief executive officer and chief financial officer (or equivalent thereof) of the issuer."],[0,"(b) Content.—The statement required under subsection (a) shall certify that the periodic report containing the financial statements fully complies with the requirements of section 13(a) or 15(d) of the Securities Exchange Act pf 1 1934 (15 U.S.C. 78m or 78o(d)) and that information contained in the periodic report fairly presents, in all material respects, the financial condition and results of operations of the issuer."],[0,"(c) Criminal Penalties.—Whoever—"],[1,"(1) certifies any statement as set forth in subsections (a) and (b) of this section knowing that the periodic report accompanying the statement does not comport with all the requirements set forth in this section shall be fined not more than $1,000,000 or imprisoned not more than 10 years, or both; or"],[1,"(2) willfully certifies any statement as set forth in subsections (a) and (b) of this section knowing that the periodic report accompanying the statement does not comport with all the requirements set forth in this section shall be fined not more than $5,000,000, or imprisoned not more than 20 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1350?type=usc&year=mostrecent&link-type=html"},"head":"§1350. Failure of corporate officers to certify financial reports","tname":"Crimes and Criminal Procedure","by":{"0":"5, 35","2":"23, 39, 17, 39","3":"10","4":"15"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"0":"4"}},{"t":"reg","label":"17 C.F.R. pt. 210","url":"https://www.ecfr.gov/current/title-17/part-210","by":{"0":"9"}},{"t":"reg","label":"17 C.F.R. pt. 229","url":"https://www.ecfr.gov/current/title-17/part-229","by":{"0":"9"}},{"t":"reg","label":"17 C.F.R. § 229.303","url":"https://www.ecfr.gov/current/title-17/section-229.303","subs":["(a)(3)(ii)","(b)(2)(ii)"],"by":{"0":"4, 9, 10, 3, 10, 42"}},{"t":"reg","label":"17 C.F.R. § 240.10b-5","url":"https://www.ecfr.gov/current/title-17/section-240.10b-5","subs":["(a)","(b)","(c)"],"by":{"0":"1, 2, 4, 5, 16, 17, 21, 22, 24, 26, 28, 7, 23, 1, 2, 7, 16, 21, 22, 26, 7, 23","4":"1, 4, 9, 10, 11, 12, 13, 1, 4, 5, 6, 7, 8, 14, 1, 4, 9, 10, 11, 12, 13"}},{"t":"reg","label":"OTHER AUTHORITIES Adoption of Disclosure Regulation & Amendments of Disclosure Forms and Rules, Securities Act Release No. 5893, 42 Fed. Reg. 65,554","url":"https://www.govinfo.gov/link/fr/42/65554","by":{"0":"9"}},{"t":"reg","label":"Management’s Discussion & Analysis of Financial Condition & Results of Operations, Exchange Act Release No. 26831, 54 Fed. Reg. 22,427","url":"https://www.govinfo.gov/link/fr/54/22427","by":{"0":"9, 41, 42, 43","2":"5-6, 43","3":"4, 27"}},{"t":"reg","label":"SEC Guidance Regarding Management’s Discussion & Analysis of Financial Condition & Results of Operations, Exchange Act Release No. 48960, 68 Fed. Reg. 75,056","url":"https://www.govinfo.gov/link/fr/68/75056","by":{"0":"44","2":"6","3":"5"}},{"t":"case","label":"Dura Pharmaceuticals, Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"sum":"The Court held that an inflated purchase price did not by itself prove \"loss causation.\" At most, an inflated purchase price suggested that misrepresentation \"touched upon\" a later economic loss, but did not necessarily cause it.","sumSrc":"Oyez","by":{"1":"2","3":"3"}},{"t":"case","label":"Hutchison v. Deutsche Bank Securities Inc.","cite":"647 F.3d 479","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/647/479/","by":{"1":"8"}},{"t":"case","label":"Lawrence v. Chater","cite":"516 U.S. 163","y":1996,"id":"1995/94-9323","sc":1,"op":2,"sum":"In a 7-2 per curiam opinion, the Court held that it had the power to issue a GVR order and that such an order is an appropriate exercise of its discretionary certiorari jurisdiction. \"In an appropriate case, a GVR order conserves the scarce resources of this Court that might otherwise be expended on plenary consideration, assists the court below by flagging a particular issue that it does not appear to have fully considered, assists this Court by procuring the benefit of the lower court's insight before we rule on the merits, and alleviates the 'potential for unequal treatment' that is inherent in our inability to grant plenary review of all pending cases raising similar issues,\" stated the unsigned opinion.","sumSrc":"Oyez","by":{"1":"9"}},{"t":"case","label":"Rombach v. Chang","cite":"355 F.3d 164","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/355/164/","by":{"1":"9"}},{"t":"case","label":"Stadnick v. Vivint Solar, Inc.","cite":"861 F.3d 31","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/861/31/","by":{"1":"8"}},{"t":"case","label":"Aaron v. SEC","cite":"446 U.S. 680","y":1980,"id":"1979/79-66","sc":1,"sum":"The Court held that plain language and the legislative history of the statutes required the SEC to establish defendant’s intent to “deceive, manipulate, or defraud” for violations of Section 10(b) and the part of Section 17(a) that specifically refers to the use of a device, scheme, or artifice with intent to defraud.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Amgen Inc. v. Connecticut Ret. Plans & Tr. Funds","cite":"568 U.S. 455","y":2013,"id":"2012/11-1085","sc":1,"sum":"The Court held that during class certification, the court does not need proof of materiality and does not have to allow the defendant to present evidence to rebut the certification.","sumSrc":"Oyez","by":{"2":"3, 4","3":"33"}},{"t":"case","label":"Direct Benefits, LLC v. TAC Fin., Inc.","cite":"2020 WL 2769982","y":2020,"court":"D. Md. May 28","by":{"2":"46"}},{"t":"case","label":"Durland v. United States","cite":"161 U.S. 306","y":1896,"id":"scdb/1895-139","sc":1,"sum":"The provision in Rev. Stat. § 5480, as amended by the act of March 2, 1889, c. 393, 25 Stat. 873, that “ if any person having devised or intending to devise any scheme or artifice to defraud... to be effected by either opening or intending to open correspondence or communication with any person, whether resident within or outside the United States, by means of the Post Office Establishment of the United States, or …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"El Paso Nat. Gas Co. v. Neztsosie","cite":"526 U.S. 473","y":1999,"id":"1998/98-6","sc":1,"sum":"Delivered by Justice David H. Souter, the Court held that requiring a district court to stay its hand while a tribal court determines its own jurisdiction, or the doctrine of tribal court exhaustion, does not apply in this case, which if brought in a state court would be subject to removal. \"By the Price-Anderson Act's unusual preemption provision Congress expressed an unmistakable preference for a federal forum, at the behest of the defending party,\" wrote Justice Souter.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Ferber v. Travelers Corp.","cite":"802 F. Supp. 698","y":1992,"court":"D. Conn.","url":"https://www.courtlistener.com/c/F.%20Supp./802/698/","by":{"2":"36"}},{"t":"case","label":"Genesis Healthcare Corp. v. Symczyk","cite":"569 U.S. 66","y":2013,"id":"2012/11-1059","sc":1,"sum":"The Court held that a collective action suit on behalf of other \"similarly situated\" employees becomes moot when the individual claim does.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Goldsmith v. Rawl","cite":"755 F. Supp. 96","y":1991,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./755/96/","by":{"2":"46"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"ar":2,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"2":"31, 35-36","3":"29, 30, 32, 33","4":"12"}},{"t":"case","label":"Herman & MacLean v. Huddleston","cite":"459 U.S. 375","y":1983,"id":"1982/81-680","sc":1,"sum":"Alleging that they were defrauded by misrepresentations in a registration statement and prospectus for certain securities, purchasers of such securities brought a class action in Federal District Court against most of the participants in the offering, seeking recovery under § 10(b) of the Securities Exchange Act of 1934 (1934 Act), which makes it unlawful for \"any\" person to use \"any\" manipulative or deceptive …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"30-31","3":"31"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"sum":"Petitioner Izumi Seimitsu Kogyo Kabushiki Kaisha was a party at the first trial in an action brought against it and respondent Windmere Corporation by respondent U. S. Philips Corporation, but was not a party to the second trial, in which Windmere prevailed. While the judgments from the second trial were on appeal, respondents reached a settlement and filed a joint motion to vacate the District Court's judgments. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49"}},{"t":"case","label":"Junius Constr. Corp. v. Cohen","cite":"178 N.E. 672","y":1931,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./178/672/","ar":2,"by":{"2":"22","3":"15, 17, 18"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Dabit","cite":"547 U.S. 71","y":2006,"id":"2005/04-1371","sc":1,"sum":"The Court held that \"holder\" class actions such as Dabit's are \"in connection with the purchase or sale\" of a security and therefore are pre-empted by SLUSA.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Republic of Argentina v. NML Cap., Ltd.","cite":"573 U.S. 134","y":2014,"id":"2013/12-842","sc":1,"sum":"The Court held that, under the Foreign Sovereign Immunities Act, property held within the US by foreign nations cannot be attached to civil claims unless certain exceptions are met.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"SEC v. Capital Gains Rsch. Bureau, Inc.","cite":"375 U.S. 180","y":1963,"id":"1963/42","sc":1,"by":{"2":"2, 46"}},{"t":"case","label":"SEC v. Das","cite":"2010 WL 4615336","y":2010,"court":"D. Neb. Nov. 4","by":{"2":"41"}},{"t":"case","label":"SEC v. Kovzan","cite":"807 F. Supp. 2d 1024","y":2011,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/807/1024/","by":{"2":"41"}},{"t":"case","label":"SEC v. Zandford","cite":"535 U.S. 813","y":2002,"id":"2001/01-147","sc":1,"sum":"The Court held that assuming that the complaint's allegations were true, the securities broker's conduct was in connection with the purchase or sale of any security.","sumSrc":"Oyez","by":{"2":"2, 24, 25, 30, 47","3":"2, 24","4":"10"}},{"t":"case","label":"Shaw v. Digital Equip. Corp.","cite":"82 F.3d 1194","y":1996,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/82/1194/","by":{"2":"36-37","4":"6"}},{"t":"case","label":"Snellink v. Gulf Res., Inc.","cite":"870 F. Supp. 2d 930","y":2012,"court":"C.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/870/930/","by":{"2":"46"}},{"t":"case","label":"Thompson v. Western States Med. Ctr.","cite":"535 U.S. 357","y":2002,"id":"2001/01-344","sc":1,"sum":"The Court held that the FDAMA's provisions amounted to unconstitutional restrictions on commercial speech.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Trans World Airlines, Inc. v. Thurston","cite":"469 U.S. 111","y":1985,"id":"1984/83-997","sc":1,"sum":"The Age Discrimination in Employment Act (ADEA) was amended in 1978 to prohibit the mandatory retirement of a protected employee because of his age. Concerned that its retirement policy, at least as it applied to flight engineers, violated the ADEA, petitioner Trans World Airlines (TWA) adopted a plan permitting any employee in \"flight engineer status\" at age 60 to continue working in that capacity. The plan, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"United States v. Naftalin","cite":"441 U.S. 768","y":1979,"id":"1978/78-561","sc":1,"sum":"Section 17 (a) (1) prohibits frauds against brokers as well as investors.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"34"}},{"t":"case","label":"Wharf (Holdings) Ltd. v. United Int’l Holdings, Inc.","cite":"532 U.S. 588","y":2001,"id":"2000/00-347","sc":1,"sum":"The Court held that an oral agreement to give an option to buy stock while secretly intending never to honor that option violates the Securities Exchange Act of 1934's prohibition of deceptive devices. Justice Breyer wrote for the Court that there was no \"convincing reason to interpret the Act to exclude oral contracts as a class.","sumSrc":"Oyez","by":{"2":"21, 25, 36, 44","3":"30","4":"10"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","stext":{"head":"§3729. False claims","paras":[[0,"(a) Liability for Certain Acts.—"],[1,"(1) In general.—Subject to paragraph (2), any person who—"],[2,"(A) knowingly presents, or causes to be presented, a false or fraudulent claim for payment or approval;"],[2,"(B) knowingly makes, uses, or causes to be made or used, a false record or statement material to a false or fraudulent claim;"],[2,"(C) conspires to commit a violation of subparagraph (A), (B), (D), (E), (F), or (G);"],[2,"(D) has possession, custody, or control of property or money used, or to be used, by the Government and knowingly delivers, or causes to be delivered, less than all of that money or property;"],[2,"(E) is authorized to make or deliver a document certifying receipt of property used, or to be used, by the Government and, intending to defraud the Government, makes or delivers the receipt without completely knowing that the information on the receipt is true;"],[2,"(F) knowingly buys, or receives as a pledge of an obligation or debt, public property from an officer or employee of the Government, or a member of the Armed Forces, who lawfully may not sell or pledge property; or"],[2,"(G) knowingly makes, uses, or causes to be made or used, a false record or statement material to an obligation to pay or transmit money or property to the Government, or knowingly conceals or knowingly and improperly avoids or decreases an obligation to pay or transmit money or property to the Government,"],[1,"is liable to the United States Government for a civil penalty of not less than $5,000 and not more than $10,000, as adjusted by the Federal Civil Penalties Inflation Adjustment Act of 1990 (28 U.S.C. 2461 note; Public Law 104–410 1), plus 3 times the amount of damages which the Government sustains because of the act of that person."],[1,"(2) Reduced damages.—If the court finds that—"],[2,"(A) the person committing the violation of this subsection furnished officials of the United States responsible for investigating false claims violations with all information known to such person about the violation within 30 days after the date on which the defendant first obtained the information;"],[2,"(B) such person fully cooperated with any Government investigation of such violation; and"],[2,"(C) at the time such person furnished the United States with the information about the violation, no criminal prosecution, civil action, or administrative action had commenced under this title with respect to such violation, and the person did not have actual knowledge of the existence of an investigation into such violation,"],[1,"the court may assess not less than 2 times the amount of damages which the Government sustains because of the act of that person."],[1,"(3) Costs of civil actions.—A person violating this subsection shall also be liable to the United States Government for the costs of a civil action brought to recover any such penalty or damages."],[0,"(b) Definitions.—For purposes of this section—"],[1,"(1) the terms \"knowing\" and \"knowingly\"—"],[2,"(A) mean that a person, with respect to information—"],[3,"(i) has actual knowledge of the information;"],[3,"(ii) acts in deliberate ignorance of the truth or falsity of the information; or"],[3,"(iii) acts in reckless disregard of the truth or falsity of the information; and"],[2,"(B) require no proof of specific intent to defraud;"],[1,"(2) the term \"claim\"—"],[2,"(A) means any request or demand, whether under a contract or otherwise, for money or property and whether or not the United States has title to the money or property, that—"],[3,"(i) is presented to an officer, employee, or agent of the United States; or"],[3,"(ii) is made to a contractor, grantee, or other recipient, if the money or property is to be spent or used on the Government's behalf or to advance a Government program or interest, and if the United States Government—"],[4,"(I) provides or has provided any portion of the money or property requested or demanded; or"],[4,"(II) will reimburse such contractor, grantee, or other recipient for any portion of the money or property which is requested or demanded; and"],[2,"(B) does not include requests or demands for money or property that the Government has paid to an individual as compensation for Federal employment or as an income subsidy with no restrictions on that individual's use of the money or property;"],[1,"(3) the term \"obligation\" means an established duty, whether or not fixed, arising from an express or implied contractual, grantor-grantee, or licensor-licensee relationship, from a fee-based or similar relationship, from statute or regulation, or from the retention of any overpayment; and"],[1,"(4) the term \"material\" means having a natural tendency to influence, or be capable of influencing, the payment or receipt of money or property."],[0,"(c) Exemption From Disclosure.—Any information furnished pursuant to subsection (a)(2) shall be exempt from disclosure under section 552 of title 5."],[0,"(d) Exclusion.—This section does not apply to claims, records, or statements made under the Internal Revenue Code of 1986."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3729?type=usc&year=mostrecent&link-type=html"},"head":"§3729. False claims","tname":"Money and Finance","by":{"2":"14, 22, 39","3":"11"}},{"t":"usc","label":"15 U.S.C. § 7241","url":"https://www.law.cornell.edu/uscode/text/15/7241","subs":["(a)(2)"],"stext":{"head":"§7241. Corporate responsibility for financial reports","paras":[[0,"(a) Regulations required"],[0,"The Commission shall, by rule, require, for each company filing periodic reports under section 78m(a) or 78o(d) of this title, that the principal executive officer or officers and the principal financial officer or officers, or persons performing similar functions, certify in each annual or quarterly report filed or submitted under either such section of this title that—"],[1,"(1) the signing officer has reviewed the report;"],[1,"(2) based on the officer's knowledge, the report does not contain any untrue statement of a material fact or omit to state a material fact necessary in order to make the statements made, in light of the circumstances under which such statements were made, not misleading;"],[1,"(3) based on such officer's knowledge, the financial statements, and other financial information included in the report, fairly present in all material respects the financial condition and results of operations of the issuer as of, and for, the periods presented in the report;"],[1,"(4) the signing officers—"],[2,"(A) are responsible for establishing and maintaining internal controls;"],[2,"(B) have designed such internal controls to ensure that material information relating to the issuer and its consolidated subsidiaries is made known to such officers by others within those entities, particularly during the period in which the periodic reports are being prepared;"],[2,"(C) have evaluated the effectiveness of the issuer's internal controls as of a date within 90 days prior to the report; and"],[2,"(D) have presented in the report their conclusions about the effectiveness of their internal controls based on their evaluation as of that date;"],[1,"(5) the signing officers have disclosed to the issuer's auditors and the audit committee of the board of directors (or persons fulfilling the equivalent function)—"],[2,"(A) all significant deficiencies in the design or operation of internal controls which could adversely affect the issuer's ability to record, process, summarize, and report financial data and have identified for the issuer's auditors any material weaknesses in internal controls; and"],[2,"(B) any fraud, whether or not material, that involves management or other employees who have a significant role in the issuer's internal controls; and"],[1,"(6) the signing officers have indicated in the report whether or not there were significant changes in internal controls or in other factors that could significantly affect internal controls subsequent to the date of their evaluation, including any corrective actions with regard to significant deficiencies and material weaknesses."],[0,"(b) Foreign reincorporations have no effect"],[0,"Nothing in this section shall be interpreted or applied in any way to allow any issuer to lessen the legal force of the statement required under this section, by an issuer having reincorporated or having engaged in any other transaction that resulted in the transfer of the corporate domicile or offices of the issuer from inside the United States to outside of the United States."],[0,"(c) Deadline"],[0,"The rules required by subsection (a) shall be effective not later than 30 days after July 30, 2002."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/7241?type=usc&year=mostrecent&link-type=html"},"head":"§7241. Corporate responsibility for financial reports","tname":"Commerce and Trade","by":{"2":"19","3":"10"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","by":{"2":"2, 11-12, 14, 27, 32-34"}},{"t":"usc","label":"15 U.S.C. § 77q","url":"https://www.law.cornell.edu/uscode/text/15/77q","subs":["(a)","(a)(2)"],"stext":{"head":"§77q. Fraudulent interstate transactions","paras":[[0,"(a) Use of interstate commerce for purpose of fraud or deceit"],[0,"It shall be unlawful for any person in the offer or sale of any securities (including security-based swaps) or any security-based swap agreement (as defined in section 78c(a)(78) 1 of this title) by the use of any means or instruments of transportation or communication in interstate commerce or by use of the mails, directly or indirectly—"],[1,"(1) to employ any device, scheme, or artifice to defraud, or"],[1,"(2) to obtain money or property by means of any untrue statement of a material fact or any omission to state a material fact necessary in order to make the statements made, in light of the circumstances under which they were made, not misleading; or"],[1,"(3) to engage in any transaction, practice, or course of business which operates or would operate as a fraud or deceit upon the purchaser."],[0,"(b) Use of interstate commerce for purpose of offering for sale"],[0,"It shall be unlawful for any person, by the use of any means or instruments of transportation or communication in interstate commerce or by the use of the mails, to publish, give publicity to, or circulate any notice, circular, advertisement, newspaper, article, letter, investment service, or communication which, though not purporting to offer a security for sale, describes such security for a consideration received or to be received, directly or indirectly, from an issuer, underwriter, or dealer, without fully disclosing the receipt, whether past or prospective, of such consideration and the amount thereof."],[0,"(c) Exemptions of section 77c not applicable to this section"],[0,"The exemptions provided in section 77c of this title shall not apply to the provisions of this section."],[0,"(d) Authority with respect to security-based swap agreements"],[0,"The authority of the Commission under this section with respect to security-based swap agreements (as defined in section 78c(a)(78) of this title) shall be subject to the restrictions and limitations of section 77b–1(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77q?type=usc&year=mostrecent&link-type=html"},"head":"§77q. Fraudulent interstate transactions","tname":"Commerce and Trade","by":{"2":"34, 14, 31-32, 14, 32","4":"6"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","stext":{"head":"§78a. Short title","paras":[[0,"This chapter may be cited as the \"Securities Exchange Act of 1934.\""]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78a?type=usc&year=mostrecent&link-type=html"},"head":"§78a. Short title","tname":"Commerce and Trade","by":{"2":"1-2, 4, 11-13, 16, 26, 31, 36, 45-46","3":"3"}},{"t":"reg","label":"Concept Release on Management’s Discussion and Analysis of Financial Condition and Operations, 52 Fed. Reg. 13,715","url":"https://www.govinfo.gov/link/fr/52/13715","by":{"2":"5"}},{"t":"reg","label":"Management’s Discussion and Analysis, Selected Financial Data, and Supplementary Financial Information, 86 Fed. Reg. 2080","url":"https://www.govinfo.gov/link/fr/86/2080","by":{"2":"7","3":"4, 27"}},{"t":"reg","label":"Selective Disclosure and Insider Trading, 65 Fed. Reg. 51,716","url":"https://www.govinfo.gov/link/fr/65/51716","by":{"2":"41","3":"25"}},{"t":"case","label":"Br. for the United States as Amicus Curiae Supporting Respondents, Leidos, Inc. v. Indiana Pub. Ret. Sys.","cite":"137 S. Ct. 1395","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/1395/","sc":1,"by":{"2":"23, 41"}},{"t":"case","label":"Pl. SEC’s Bench Mem. in Opp. to Def. Conaway’s Mot. for J. as a Matter of Law, SEC v. Conaway","cite":"698 F. Supp. 2d 771","y":2010,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/698/771/","by":{"2":"41","3":"25"}},{"t":"case","label":"Fischman v. Raytheon Mfg. Co.","cite":"188 F.2d 783","y":1951,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/188/783/","by":{"3":"21"}},{"t":"case","label":"Gallagher v. Abbott Labs.","cite":"269 F.3d 806","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/269/806/","by":{"3":"19"}},{"t":"case","label":"Glazer v. Dress Barn, Inc.","cite":"873 A.2d 929","y":2005,"court":"Conn.","url":"https://www.courtlistener.com/c/A.2d/873/929/","by":{"3":"19"}},{"t":"case","label":"Leidos, Inc. v. Indiana Pub. Ret. Sys.","cite":"138 S. Ct. 2670","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/2670/","sc":1,"by":{"3":"16"}},{"t":"case","label":"Lindner Fund, Inc. v. Waldbaum, Inc.","cite":"624 N.E.2d 160","y":1993,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/624/160/","by":{"3":"19"}},{"t":"case","label":"MBIA Ins. Corp. v. Royal Indem. Co.","cite":"426 F.3d 204","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/426/204/","by":{"3":"14"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"3":"28"}},{"t":"case","label":"Rodopoulos v. Sam Piki Enters., Inc.","cite":"570 So.2d 661","y":1990,"court":"Ala.","url":"https://www.courtlistener.com/c/So.2d/570/661/","by":{"3":"19"}},{"t":"usc","label":"15 U.S.C. § 78l","url":"https://www.law.cornell.edu/uscode/text/15/78l","subs":["(b)(1)(A)"],"by":{"3":"3"}},{"t":"reg","label":"7 Fed. Reg. 3799","url":"https://www.govinfo.gov/link/fr/7/3799","by":{"3":"29"}},{"t":"reg","label":"47 Fed. Reg. 11,474","url":"https://www.govinfo.gov/link/fr/47/11474","by":{"3":"4"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"8"}},{"t":"usc","label":"15 U.S.C. § 78u-5","url":"https://www.law.cornell.edu/uscode/text/15/78u-5","subs":["(i)(1)(C)"],"by":{"4":"19"}}]};